{
  "decision-match-unlabeled-copy-removals": "WITH requests AS (SELECT line_no, depot_code, edition_code, ROW_NUMBER() OVER (PARTITION BY depot_code, edition_code ORDER BY line_no) AS copy_no FROM copy_requests), completed AS (SELECT depot_code, edition_code, SUM(copy_qty) AS copies FROM removal_tally GROUP BY depot_code, edition_code) SELECT r.line_no, r.depot_code, r.edition_code FROM requests AS r LEFT JOIN completed AS c ON c.depot_code = r.depot_code AND c.edition_code IS r.edition_code WHERE r.copy_no > COALESCE(c.copies, 0) ORDER BY r.line_no",
  "decision-matched-store-lift-with-balanced-pairs": "WITH RECURSIVE effects AS (SELECT ROW_NUMBER() OVER (ORDER BY t.pair_code) AS i, (t.post_units - t.pre_units) * c.weeks_n - (c.post_units - c.pre_units) * t.weeks_n AS num, t.weeks_n * c.weeks_n AS den FROM store_period AS t JOIN store_period AS c ON c.pair_code = t.pair_code AND c.arm_code = 'control' WHERE t.arm_code = 'trial' AND t.pre_units IS NOT NULL AND t.post_units IS NOT NULL AND c.pre_units IS NOT NULL AND c.post_units IS NOT NULL), totals(i, num, den) AS (SELECT 0, 0, 1 UNION ALL SELECT e.i, s.num * e.den + e.num * s.den, s.den * e.den FROM totals AS s JOIN effects AS e ON e.i = s.i + 1), scaled AS (SELECT i AS complete_pairs, 100 * num AS n, i * den AS d FROM totals ORDER BY i DESC LIMIT 1) SELECT complete_pairs, CASE WHEN n < 0 THEN -1 ELSE 1 END * ((ABS(n) + d / 2) / NULLIF(d, 0)) AS mean_lift_hundredths FROM scaled",
  "decision-maximize-packed-production-mix": "WITH qty(n) AS (VALUES (0), (1), (2), (3), (4)), mixes AS (SELECT x.n AS a_units, y.n AS b_units, x.n + y.n AS total_units, x.n * a.slots_per_unit + y.n * b.slots_per_unit AS slots_used, x.n * a.staff_minutes_per_unit + y.n * b.staff_minutes_per_unit AS staff_minutes_used FROM qty AS x CROSS JOIN qty AS y CROSS JOIN product AS a CROSS JOIN product AS b WHERE a.product_code = 'A' AND b.product_code = 'B') SELECT a_units, b_units, total_units, slots_used, staff_minutes_used FROM mixes CROSS JOIN shift WHERE slots_used <= packing_slots AND staff_minutes_used <= staff_minutes ORDER BY total_units DESC, a_units DESC LIMIT 1",
  "decision-measure-margin-after-graded-returns": "WITH returns AS (SELECT lot_code, SUM(refund_units) AS refunded, SUM(shelf_units) AS restocked FROM return_check GROUP BY lot_code), margins AS (SELECT l.sku_code, SUM((l.sold_units - COALESCE(r.refunded, 0)) * l.unit_price) AS net_sales_cents, SUM((l.sold_units - COALESCE(r.restocked, 0)) * l.unit_cost) AS net_cost_cents FROM sale_lot AS l LEFT JOIN returns AS r ON r.lot_code = l.lot_code GROUP BY l.sku_code) SELECT sku_code, net_sales_cents, net_cost_cents, net_sales_cents - net_cost_cents AS gross_margin_cents FROM margins ORDER BY sku_code COLLATE BINARY ASC"
}
